/* Live source viewing is read-only. A fetched page is evidence, not an auto-approved degree audit. */
let sourceViewToken=0;
function sourceLibrary(){return journeyPage(3,'Your plan should have receipts.',`<p class="journey-lede">Open official program pages, requirements, transfer guides and deadlines. Read a current page without sending any student records.</p><div class="journey-actions"><a class="btn primary" href="#transfer-guides">Search published transfer mappings →</a><a class="btn" href="#college-catalogs">Cascadia degree catalog →</a></div><label>College<select id="source-college"><option value="">All colleges</option>${[...new Set(CollegeSources.resources.map(r=>r.college))].map(s=>`<option>${esc(s)}</option>`).join('')}</select></label><div id="source-resources" class="degree-goals"></div><section id="source-reading" class="degree-optimizer" hidden aria-live="polite"></section><p class="quiet-note">Connections are read-only and may be blocked by an institution. A page being fetched does not verify how its rules apply to a student. No access restrictions are bypassed. Source snapshots remain labeled with their review date.</p><a class="journey-secondary" href="#programs">Browse program-specific sources →</a>`,'roadmap')}
async function readOfficialSource(query,target){const token=++sourceViewToken;target.hidden=false;target.innerHTML='<p role="status">Reading the official source…</p>';try{const response=await fetch('/api/college-source?'+query,{headers:{Accept:'application/json'}}),data=await response.json();if(token!==sourceViewToken||!target.isConnected)return;if(!response.ok||data.status!=='live'){target.innerHTML=`<h3>Source needs a direct visit</h3><p>${esc(data.message||data.error||'Live source reading is unavailable on this deployment.')}</p>${ProductCore.safeURL(data.resource?.url)?`<a class="journey-secondary" href="${esc(data.resource.url)}" target="_blank" rel="noopener">Open official source ↗</a>`:''}`;return}target.innerHTML=`<span class="eyebrow">LIVE OFFICIAL SOURCE · ${esc(new Date(data.checkedAt).toLocaleString('en-US',{timeZone:'America/Los_Angeles'}))} PACIFIC</span><h3>${esc(data.resource.kind)}</h3><a class="journey-secondary" href="${esc(ProductCore.safeURL(data.finalUrl))}" target="_blank" rel="noopener">Open original ↗</a><p>Review the applicable catalog year, applicant type and full source. This text has not been converted into a verified degree audit.</p><details open><summary>Official page text</summary><pre class="source-page-text">${esc(data.text)}</pre></details>${data.links?.length?`<details><summary>Related official pages</summary>${data.links.map(l=>`<p><a class="journey-secondary" href="${esc(ProductCore.safeURL(l.url))}" target="_blank" rel="noopener">${esc(l.title)} ↗</a></p>`).join('')}</details>`:''}`}catch{if(token===sourceViewToken&&target.isConnected)target.innerHTML='<p>Could not reach the source service. Use the direct official links above.</p>'}}
function evidenceBenchmarks(){const info=AcademicEvidence.info;return `<details class="journey-advanced"><summary>Published GPA and admission context</summary><p>Official snapshots reviewed ${esc(AcademicEvidence.checked)}. Historical cohort data provides context, not personal probabilities. A middle 50% range is not an average or a cutoff.</p>${AcademicEvidence.universityBenchmarks.map(b=>`<article class="degree-goal"><span class="eyebrow">${esc(b.institution)} · ${esc(b.track)}</span><h3>${b.gpaLow.toFixed(2)}–${b.gpaHigh.toFixed(2)} GPA · middle 50%</h3><p>${esc(b.gpaCohort||b.cohort)} · ${esc(b.warning)}</p><p>${esc(b.admitRatePeriod||b.cohort)}: ${b.admitRates.map(r=>`${esc(r.group)} ${Math.round(r.rate*100)}%`).join(' · ')} historically admitted. These are institutional group rates, not your college or major admission chance.</p><a class="journey-secondary" href="${esc(b.source)}" target="_blank" rel="noopener">Official statistics ↗</a></article>`).join('')}<article class="degree-goal"><h3>Informatics: ${esc(info.gradeBenchmarks.exactHeading)}</h3><p>${esc(info.gradeBenchmarks.population)}</p><div class="table-wrap"><table><thead><tr><th>Prerequisite category</th><th>Published average grade</th><th>Published range</th></tr></thead><tbody>${info.gradeBenchmarks.rows.map(r=>`<tr><td>${esc(r.category)}</td><td>${r.average.toFixed(2)}</td><td>${r.min.toFixed(1)}–${r.max.toFixed(1)}</td></tr>`).join('')}</tbody></table></div><p>The prerequisite minimum is 2.0. These table values are not mandatory competitive targets, cumulative admitted GPAs or a prediction.</p><a class="journey-secondary" href="${esc(info.gradeBenchmarks.source)}" target="_blank" rel="noopener">Official prerequisite source ↗</a></article></details>`}
function admissionSourceRules(){return `<details class="journey-advanced"><summary>UWB EE admission and multiple-degree rules</summary><h3>Electrical Engineering admission</h3><p>Published minimum cumulative GPA: 2.7. Calculus I, Calculus II and Mechanics each require 2.3; their prerequisite average must be at least 2.6. College English composition requires 2.0. Entry is Autumn or Winter.</p><p>The source describes a minimum-requirements program and says meeting minimum entry requirements guarantees admission; it also notes holistic committee review if necessary. Camino cannot verify all eligibility conditions or make an individual admission decision.</p><a href="${AcademicEvidence.uwbEE.source}" target="_blank" rel="noopener">Official EE admission rules ↗</a><h3>Graduation and additional degrees</h3><p>UWB generally requires at least 180 credits and a 2.0 residence GPA. Residency includes 45 of the final 60 credits at the awarding UW campus; exceptions need an approved petition. A concurrent second bachelor’s requires at least 45 credits beyond the first degree's requirement. Both advisers must approve a double major. Shared courses do not waive these totals.</p><a href="${AcademicEvidence.uwbDegreeRules.source}" target="_blank" rel="noopener">Official graduation / multiple-degree rules ↗</a><p>Apply for graduation three quarters before the expected quarter. The absolute deadline is the third Friday of that quarter; use the official calendar for its date. Meet the adviser and verify the application through the UW email link. Summer graduates attending commencement must meet the Spring deadline.</p><a href="${AcademicEvidence.uwbGraduation.source}" target="_blank" rel="noopener">Official graduation application procedure ↗</a></details>`}
function addEvidenceCheckpoint(rule){if(state.profile?.applicantTrack!=='current-seattle-undergrad')return toast('These derived dates use current UW Seattle student rules. Select that route, or check the official transfer/first-year dates.');state.advisingDates||=[];const row={label:'Apply to major',date:rule.date,institution:'UW Seattle Informatics',cycle:rule.entry,track:'Current UW Seattle undergraduate',source:AcademicEvidence.info.application.source,dateBasis:rule.dateBasis};if(state.advisingDates.some(d=>d.date===row.date&&d.institution===row.institution))return toast('That checkpoint is already saved.');if(state.advisingDates.length>=40)return toast('Use up to 40 checkpoints.');state.advisingDates.push(row);state.advisingDates.sort((a,b)=>a.date.localeCompare(b.date));save();render();toast('Derived planning date added; confirm the current application cycle.')}
function applicationSourceTools(){return `<section class="degree-optimizer"><h2>Plan the application before the deadline.</h2><label>Applicant route<select id="applicant-track">${options(['Not selected','current-seattle-undergrad','transfer','first-year'],state.profile?.applicantTrack||'Not selected')}</select></label><p>Major admission and college admission use different routes. The current-Seattle checklist must not be applied to first-year or transfer applicants.</p><details><summary>Informatics annual application checkpoints</summary><p>Annual rules, not a guarantee the portal is open for a future cycle. Current Seattle applicants must finish the four prerequisites in the preceding quarter. Transfer applicants use a different checklist and a separate university application.</p>${AcademicEvidence.info.application.derivedExamples.map((r,i)=>`<article class="degree-goal"><h3>${esc(r.date)} · ${esc(r.entry)}</h3><p>${esc(r.prerequisiteTerm)} · ${esc(r.dateBasis)}</p><button class="btn" data-add-info-checkpoint="${i}">Add derived planning checkpoint</button></article>`).join('')}<a href="${AcademicEvidence.info.application.source}" target="_blank" rel="noopener">Verify the current program cycle ↗</a></details><a class="journey-secondary" href="#source-library">Read live official college sources →</a>${evidenceBenchmarks()}${admissionSourceRules()}</section>`}
function bindResearch(){const select=document.querySelector('#source-college'),list=document.querySelector('#source-resources');if(select&&list){const update=()=>{list.innerHTML=CollegeSources.resources.filter(r=>!select.value||r.college===select.value).map(r=>`<article class="degree-goal"><span class="eyebrow">${esc(r.college)}</span><h3>${esc(r.kind)}</h3><a class="journey-secondary" href="${esc(r.url)}" target="_blank" rel="noopener">Official page ↗</a><button class="btn" data-read-source="${esc(r.id)}">Read current page</button></article>`).join('');list.querySelectorAll('[data-read-source]').forEach(b=>b.onclick=()=>readOfficialSource('id='+encodeURIComponent(b.dataset.readSource),document.querySelector('#source-reading')))};select.onchange=update;update()}document.querySelector('#applicant-track')?.addEventListener('change',e=>{state.profile={...state.profile,applicantTrack:e.target.value};save()});document.querySelectorAll('[data-add-info-checkpoint]').forEach(b=>b.onclick=()=>addEvidenceCheckpoint(AcademicEvidence.info.application.derivedExamples[+b.dataset.addInfoCheckpoint]));document.querySelectorAll('[data-read-program-source]').forEach(b=>b.onclick=()=>{let target=b.parentElement.querySelector('.program-source-reader');if(!target){target=document.createElement('section');target.className='degree-optimizer program-source-reader';b.parentElement.append(target)}readOfficialSource('program='+encodeURIComponent(b.dataset.readProgramSource),target)})}
function installResearch(){const oldAdvising=advisingPage;advisingPage=()=>oldAdvising()+applicationSourceTools();const oldSources=sources;sources=()=>`<div class="degree-summary"><a class="journey-secondary" href="#source-library">Read current official requirements, deadlines and equivalency guides →</a></div>`+oldSources();const oldBind=bind;bind=()=>{oldBind();bindResearch()}}
